// Server text in the app's language. i18n.json is generated by app/scripts/i18n-sync.mjs from the app's dictionaries
// (keys server.* and push.*) as { "<lang>": { "<English text>": "<translation>" } }, so errors keep their English text
// in code. Unknown language or text → the English as written.
import { readFileSync } from 'node:fs';

const T = JSON.parse(readFileSync(new URL('./i18n.json', import.meta.url), 'utf8'));

export const say = (lang, text) => (lang && T[lang]?.[text]) || text;

/** The app sends its dictionary tag (e.g. "pt-BR") as Accept-Language. */
export function langOf(req) {
  const l = String(req.headers['accept-language'] ?? '').split(/[,;]/)[0].trim();
  return T[l] ? l : 'en';
}
